/* Transition Town School: identity → résumé → application → assigned hands-on shift. */
(function(){'use strict';
const C=window.TTCareerCore,D=window.TTCareerData,$=s=>document.querySelector(s),app=$('#app'),dialog=$('#stationDialog'),body=$('#dialogBody');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),lines=s=>esc(s).replace(/\n/g,'<br>');
let actor=sessionStorage.ttCurrent||'',project=null,archive=[],view='campus',floor='school',activeTask=-1,feedback='',stream=null,raf=0,lastFrame=0,world=null,keys={},toastTimer=0,saveTimer=0,activeAt=0,autoEntryAt=0,pen=null;
const photoKey=()=> 'ttCareerPhoto:'+actor;
function getWorld(){const w=JSON.parse(localStorage.ttWorld||'{"residents":{}}');if(!w||typeof w.residents!=='object'||Array.isArray(w.residents))throw Error('Your Town profile could not be read. Return to Town before continuing.');return w}
function resident(){try{return getWorld().residents[actor]||{}}catch{return {}}}
function job(){return D.jobs.find(j=>j.id===project?.persona?.jobId)}
function load(){try{const r=resident();project=r.careerLab?.project||null;archive=r.careerLab?.archive||[]}catch{project=null;archive=[]}}
function save(){if(!actor||sessionStorage.ttCurrent!==actor)return false;try{const w=getWorld();if(!w.residents[actor])throw Error('Return to Town and log in before saving.');w.residents[actor].careerLab={version:1,project,archive:archive.slice(-20)};localStorage.ttWorld=JSON.stringify(w);return true}catch(e){let warning=$('#saveWarning');if(!warning){warning=document.createElement('div');warning.id='saveWarning';warning.className='save-warning';document.body.prepend(warning)}warning.textContent='Progress could not be saved: '+e.message;return false}}
function laterSave(){clearTimeout(saveTimer);saveTimer=setTimeout(save,350)}
function note(kind,summary,details={}){if(!project)return;const e={at:new Date().toISOString(),kind,summary,...details};project.events.push(e);project.events=project.events.slice(-180);save();window.TTMonitor?.record(kind,summary,{action:'career-lab',scope:'school career practice',career:job()?.title,task:details.task||'',success:kind==='completed',quantity:details.quantity||0,service:details.service||'Job Exploration Counseling'});}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4400)}
function stopCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null}
function showDialog(title,html,kicker='JOB EXPLORATION',work=false){stopCamera();keys={};dialog.classList.toggle('work-dialog',work);$('#dialogTitle').textContent=title;$('#dialogKicker').textContent=kicker;body.innerHTML=html;if(!dialog.open)dialog.showModal();body.scrollTop=0;activeAt=Date.now();}
function closeDialog(){stopCamera();clearTimeout(saveTimer);save();dialog.close();activeTask=-1;keys={};if(world){world.target=null;world.cooldown=Date.now()+1400;world.moving=false}activeAt=0;}
$('#closeDialog').onclick=closeDialog;dialog.addEventListener('cancel',e=>{e.preventDefault();closeDialog()});dialog.addEventListener('close',stopCamera);window.addEventListener('pagehide',()=>{stopCamera();save()});
const stage=()=>!project?0:!project.resumeComplete?1:!project.applicationComplete?2:project.shift?.endedAt?5:3;
function hero(title,subtitle,badge='50 careers'){return `<section class="hero"><div><span class="eyebrow">TRANSITION TOWN SCHOOL / JOB EXPLORATION</span><h1>${title}</h1><p>${subtitle}</p></div><div class="hero-badge"><strong>${badge}</strong>Real decisions. Practice experience.</div></section>`}
function journey(){const labels=[['id','Practice identity','DAY 1'],['resume','Build your résumé','DAY 1'],['applications','Apply for a job','DAY 2'],['work','Assigned work shift','DAY 3'],['portfolio','Career folder','SAVE & PRINT']],n=stage();return `<div class="journey" aria-label="Project progress">${labels.map(([id,label,day],i)=>`<button data-travel="${id}" class="${n>i?'done':n===i?'now':''}"><b>${n>i?'✓':i+1}</b><span>${label}<small>${day}</small></span></button>`).join('')}</div>`}
function avatarImage(){const c=document.createElement('canvas');c.width=208;c.height=250;const x=c.getContext('2d');x.fillStyle='#e3eadb';x.fillRect(0,0,208,250);window.TTDrawAvatar(x,104,228,resident().avatar,0,false,2);return c.toDataURL('image/png')}
function portrait(){let s=localStorage.getItem(photoKey())||'';return /^data:image\/(jpeg|png);base64,[A-Za-z0-9+/=]+$/.test(s)?s:avatarImage()}
function portraitMarkup(){const owner=window.TTBusinessAvatars?.[actor],custom=localStorage.getItem('ttCareerPortraitMode:'+actor)==='photo';if(owner&&!custom){if(!owner.image)return `<span class="id-photo business-portrait business-initial" role="img" aria-label="${esc(actor)} business avatar">${esc(actor[0])}</span>`;return `<span class="id-photo business-portrait" role="img" aria-label="${esc(actor)} business avatar" style="background-image:url('${esc(owner.image)}');background-position:${esc(owner.position)};background-size:${esc(owner.size)}" data-monitor-private></span>`;}return `<img class="id-photo" src="${portrait()}" alt="Practice ID portrait" data-monitor-private>`;}
function idCard(p=project.persona){return `<article class="practice-id"><div class="id-top">TRANSITION TOWN · CAREER EXPLORATION ID</div><div class="id-row">${portraitMarkup()}<div><h3>${esc(p.name)}</h3><p>${esc(p.address)}<br>${esc(p.city)}, ${esc(p.state)} ${esc(p.zip)}</p><p>${esc(p.id)}</p><div class="id-barcode" aria-hidden="true"></div></div></div><small>FICTIONAL CLASSROOM IDENTITY · NOT GOVERNMENT IDENTIFICATION</small></article>`}
function backgroundSheet(p=project.persona,compact=true){return `<div class="${compact?'reference':''}"><h3>Your practice background</h3><p class="fine">Use these fictional details for your résumé and application.</p><h4>CONTACT</h4><p><b>${esc(p.name)}</b><br>${esc(p.address)}<br>${esc(p.city)}, ${esc(p.state)} ${esc(p.zip)}<br>${esc(p.phone)}<br>${esc(p.email)}</p><h4>CAREER INTEREST</h4><p>${esc(job()?.title)}</p><h4>EDUCATION</h4><p>${esc(p.education.qualification)}<br>${esc(p.education.school)} · ${esc(p.education.year)}</p>${p.experience.map((x,i)=>`<details ${i===0||!compact?'open':''}><summary>${i===0?'MOST RECENT EXPERIENCE':'EARLIER EXPERIENCE'}</summary><p><b>${esc(x.title)}</b><br>${esc(x.employer)}<br>${esc(x.from)} to ${esc(x.to)}</p><ul>${x.duties.map(d=>`<li>${esc(d)}</li>`).join('')}</ul></details>`).join('')}<h4>SKILLS</h4><p>${p.skills.map(esc).join(' · ')}</p><h4>REFERENCES</h4>${p.references.map(r=>`<p><b>${esc(r.name)}</b> · ${esc(r.title)}<br>${esc(r.organization)}<br>${esc(r.phone)}</p>`).join('')}<h4>AVAILABILITY</h4><p>${esc(p.availability)}<br>Available to start: ${esc(p.startDate)}</p>${compact?'<button class="secondary" data-print="identity">Print ID & background</button>':''}</div>`}
function render(){cancelAnimationFrame(raf);world=null;document.querySelectorAll('nav [data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===view));$('#learnerBadge').innerHTML=`<span class="learner-pill"><i class="online-dot"></i>${esc(actor)}</span>`;
if(!C||!D?.jobs?.length){app.innerHTML='<div class="empty">The career catalogue did not load. Refresh this page to try again.</div>';return}
if(!actor){app.innerHTML=hero('Your career starts at school.','Log in with your existing Town profile to bring your avatar and keep your career folder.')+'<section class="section-pad"><a class="primary" href="transition-town.html?next=school-career-lab.html">Log in to Transition Town</a></section>';return}
if(view==='careers')return renderCareers();if(view==='portfolio')return renderPortfolio();renderCampus();}
function renderCampus(){const n=stage(),j=job(),work=floor==='work'&&project?.assignment,task=project?.shift?.tasks.findIndex(t=>!t.completedAt)??0;app.innerHTML=hero(work?'Your shift. Your responsibility.':'A little practice. A bigger future.',work?`${esc(j.title)} · Supervisor assignment: ${esc(project.assignment.title)}. Walk to the highlighted station to begin.`:'Walk your Town avatar to a station. Get your ID, build a résumé, apply, then step into a work shift with an assigned department.',work?'ON SHIFT':'50 careers')+journey()+`<div class="campus-grid"><div class="world-wrap"><canvas id="worldCanvas" width="1100" height="760" tabindex="0" role="img" aria-label="${work?'Assigned workplace':'School career lab'} walking map. Use arrow keys or WASD, or tap a destination."></canvas><div class="world-label"><b>${work?esc(j.employer):'JOB EXPLORATION WING'}</b>${work?'SUPERVISOR ASSIGNS YOUR STATIONS':'IDENTITY · RÉSUMÉ · APPLICATION · WORK'}</div><div class="world-bottom"><div class="world-hint" id="worldHint">Tap a building or use arrow keys / WASD to walk. Enter opens a nearby station.</div><div class="dpad" aria-label="Move your character"><button data-dir="up" aria-label="Walk up">↑</button><button data-dir="left" aria-label="Walk left">←</button><button data-dir="down" aria-label="Walk down">↓</button><button data-dir="right" aria-label="Walk right">→</button></div></div></div><aside class="campus-side"><section class="side-card"><span class="day-chip">${n<2?'DAY 1 · YOUR BACKGROUND':n===2?'DAY 2 · APPLICATION':'DAY 3 · ON THE JOB'}</span><h2>${!project?'First, make it yours.':!project.resumeComplete?'Turn your background into a résumé.':!project.applicationComplete?'Put your résumé to work.':project.shift?.endedAt?'Shift complete.':work?'Your next assignment':'You have an assignment.'}</h2><p>${!project?'Choose a career interest. The school gives you a complete practice identity and work history.':!project.resumeComplete?'Your identity sheet has everything you need. Type your practice information at the résumé desk.':!project.applicationComplete?'Complete an application using your background sheet. Your supervisor will assign your department.':project.shift?.endedAt?'Review your work, print your report, and reflect with Miss Kayla.':work?esc(j.roles[project.assignment.roleIndex].tasks[Math.max(0,task)]?.brief||'All stations completed.'):esc(project.assignment.title)+' · Read your task brief and clock in.'}</p><button class="primary" data-travel="${!project?'id':!project.resumeComplete?'resume':!project.applicationComplete?'applications':project.shift?.endedAt?'portfolio':'work'}">${!project?'Get my practice ID':!project.resumeComplete?'Go to résumé desk':!project.applicationComplete?'Go to application desk':project.shift?.endedAt?'Open career folder':work?'See my shift brief':'Start my assigned shift'} →</button></section><section class="side-card"><h3>Your three-day project</h3><ol><li><b>Day 1:</b> ID, background sheet, résumé.</li><li><b>Day 2:</b> Career research and application.</li><li><b>Day 3:</b> Assigned role, hands-on tasks, reflection.</li></ol><p>Move at your pace. Progress stays with your Town profile on this device.</p>${work?'<button class="quiet" data-floor="school">Back to school wing</button>':'<button class="quiet" data-nav="portfolio">Save & print my work</button>'}</section></aside></div>`;startWorld(work);}
function renderCareers(){app.innerHTML=hero('Find a future that fits.','Explore 50 careers, from first jobs to skilled trades and professional pathways. Choose a career interest; your supervisor assigns the work role.')+journey()+`<section class="section-pad"><div class="filterbar"><input id="careerSearch" type="search" placeholder="Search careers, skills, or workplaces…" aria-label="Search careers"><select id="careerLevel" aria-label="Training level"><option value="">Every training path</option><option>Entry</option><option>Training</option><option>Degree</option><option>Professional</option></select><select id="careerCluster" aria-label="Career field"><option value="">Every career field</option>${[...new Set(D.jobs.map(j=>j.cluster))].sort().map(c=>`<option>${esc(c)}</option>`).join('')}</select></div><p class="fine" id="careerCount" role="status"></p><div id="careerGrid" class="career-grid"></div></section>`;filterCareers();$('#careerSearch').oninput=filterCareers;$('#careerLevel').onchange=filterCareers;$('#careerCluster').onchange=filterCareers;}
function filterCareers(){const q=$('#careerSearch').value.toLowerCase(),level=$('#careerLevel').value,cluster=$('#careerCluster').value,jobs=D.jobs.filter(j=>(!level||j.level===level)&&(!cluster||j.cluster===cluster)&&[j.title,j.summary,j.cluster,...j.skills].join(' ').toLowerCase().includes(q));$('#careerCount').textContent=jobs.length+' of 50 careers';$('#careerGrid').innerHTML=jobs.map(j=>`<article class="career-card" style="--career:${j.color}"><div class="career-icon" aria-hidden="true">${esc(j.title.split(' ').map(w=>w[0]).slice(0,2).join(''))}</div><span class="tag">${esc(j.cluster)} · ${esc(j.level)}</span><h2>${esc(j.title)}</h2><p>${esc(j.summary)}</p><p class="route"><b>Typical path:</b> ${esc(j.route)}</p><button class="secondary" data-career="${j.id}">Explore this career →</button></article>`).join('')||'<div class="empty">No matches yet. Try a skill such as organizing, caring, or drawing.</div>';}
function careerDetail(id){const j=D.jobs.find(j=>j.id===id);if(!j)return;showDialog(j.title,`<p class="instruction">${esc(j.summary)}</p><div class="form-grid"><div><h3>The pathway</h3><p>${esc(j.route)}</p><p class="fine">Actual training, age, licensing, and employer requirements vary. The background you receive here is fictional classroom practice.</p><a href="${esc(j.source)}" target="_blank" rel="noopener" class="text-link">Explore the official career profile ↗</a></div><div><h3>What you will practice</h3><ul>${[...new Set(j.roles.flatMap(r=>r.tasks.map(t=>t.title)))].slice(0,7).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div></div><h3>Supervisor-assigned departments</h3><p>${j.roles.map(r=>esc(r.title)).join(' / ')}</p><p>You apply for the career. The school assigns your department; you do not choose a work station.</p><div class="button-row"><button class="primary" data-identity-job="${id}">${project?.persona.jobId===id?'View my practice identity':'Use this career interest'}</button></div>`,'50 CAREERS / CAREER RESEARCH');}
function openIdentity(id){if(project&&!id){showID();return}if(project&&id===project.persona.jobId){showID();return}showDialog('Your practice identity',`<p>Choose a career interest. The school will create your fictional name, Town address, education, experience, and references.</p>${project?'<p class="instruction">Starting another career keeps your current project in your folder history.</p>':''}<form id="identityForm"><div class="form-grid"><label class="wide">Career interest<select name="career" required><option value="">Choose a career…</option>${D.jobs.map(j=>`<option value="${j.id}" ${id===j.id?'selected':''}>${esc(j.title)} · ${esc(j.level)}</option>`).join('')}</select></label></div><div class="button-row"><button class="primary">Create my practice ID</button></div></form><p class="fine">Your existing Town avatar comes with you. You can optionally take an ID photo after your card is created.</p>`,'DAY 1 / IDENTITY DESK');$('#identityForm').onsubmit=e=>{e.preventDefault();const j=D.jobs.find(j=>j.id===new FormData(e.target).get('career'));if(!j)return;if(project)archive.push(project);project=C.newProject(actor,j,archive.length);save();note('completed','Created practice identity for '+j.title);showID()};}
function showID(){if(!project)return openIdentity();showDialog('Your next chapter starts here.',`${idCard()}<div class="button-row"><button class="primary" data-print="identity">Print ID & full background</button><button class="secondary" data-photo="open">Take / change ID photo</button><button class="quiet" data-travel="resume">Walk to résumé desk →</button></div><div class="instruction">Save this screen or print the full background. Use these details as you fill out your résumé and application.</div>${backgroundSheet(project.persona,false)}`,'DAY 1 / YOUR PRACTICE ID');}
async function openPhoto(){showDialog('Your ID portrait',`<p>Your existing business avatar is used on your ID when one is assigned. You can take a photo or choose one from this device.</p><div data-monitor-private><video id="cameraVideo" class="camera-frame" playsinline autoplay muted hidden></video><div id="photoPreview">${portraitMarkup()}</div><p id="cameraMessage" role="status"></p><div class="button-row"><button class="primary" data-photo="start">Turn on camera</button><button class="primary" data-photo="capture" id="capturePhoto" hidden>Take photo</button><label class="secondary">Choose photo<input id="photoFile" type="file" accept="image/jpeg,image/png,image/webp" capture="user" hidden></label><button class="quiet" data-photo="avatar">Use my business avatar</button></div></div><p class="fine">The portrait stays on this device and appears on your printed ID. Camera access is optional.</p>`,'IDENTITY DESK / OPTIONAL PHOTO');$('#photoFile').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!/^image\/(jpeg|png|webp)$/.test(f.type)||f.size>10*1024*1024){$('#cameraMessage').textContent='Choose a JPG, PNG, or WebP photo smaller than 10 MB.';return}const reader=new FileReader();reader.onload=()=>{const im=new Image();im.onload=()=>savePortrait(im);im.src=reader.result};reader.readAsDataURL(f)};}
async function startCamera(){try{if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera access is not available here. You can choose a photo or keep your avatar.');stopCamera();const requested=await navigator.mediaDevices.getUserMedia({video:{facingMode:'user',width:{ideal:640},height:{ideal:480}},audio:false});if(!dialog.open||!$('#cameraVideo')){requested.getTracks().forEach(t=>t.stop());return}stream=requested;const v=$('#cameraVideo');v.srcObject=stream;v.hidden=false;$('#photoPreview').hidden=true;$('#capturePhoto').hidden=false;$('#cameraMessage').textContent='Line up your face, then choose Take photo.';await v.play()}catch(e){if($('#cameraMessage'))$('#cameraMessage').textContent=e.name==='NotAllowedError'?'Camera permission was declined. Choose a photo or keep your Town avatar.':e.message;}}
function savePortrait(im){const w=im.videoWidth||im.naturalWidth,h=im.videoHeight||im.naturalHeight;if(!w||!h)return;const c=document.createElement('canvas');c.width=240;c.height=300;const x=c.getContext('2d'),sw=Math.min(w,h*.8),sh=sw/0.8;x.drawImage(im,(w-sw)/2,(h-sh)/2,sw,sh,0,0,240,300);try{localStorage.setItem(photoKey(),c.toDataURL('image/jpeg',.8));localStorage.setItem('ttCareerPortraitMode:'+actor,'photo');stopCamera();showID();toast('Your ID portrait is saved on this device.')}catch{stopCamera();toast('The photo could not be saved. Your avatar is still available.')}}
function fields(values,defs){return defs.map(([name,label,type='text',wide=false])=>`<label class="${wide?'wide':''}">${label}${type==='textarea'?`<textarea name="${name}" data-draft>${esc(values[name]||'')}</textarea>`:`<input name="${name}" type="${type}" value="${esc(values[name]||'')}" data-draft required ${name==='phone'||name==='referencePhone'?'inputmode="tel"':''}>`}</label>`).join('')}
function readForm(form){const obj=Object.fromEntries(new FormData(form));if(form.id==='applicationForm')obj.certify=form.elements.certify.checked;return obj}
function openResume(){if(!project)return travel('id');showDialog('Build your résumé.',`<div class="split-form"><form id="resumeForm"><p>Use your practice background. Turn the experience into clear résumé statements.</p><div class="form-grid">${fields(project.resume,[['name','Full practice name'],['phone','Practice phone','tel'],['email','Practice email','email'],['address','Street address'],['objective','Career objective','textarea',true],['education','Education · qualification, school, year','textarea',true],['experience','Experience · employers, dates, and duties','textarea',true],['skills','Skills that fit this career','textarea',true]])}</div><div id="formFeedback" role="status"></div><div class="button-row"><button class="primary">Check & save my résumé</button><button type="button" class="quiet" data-print="resume">Print résumé draft</button></div><p class="fine">Your draft saves as you type on this device.</p></form>${backgroundSheet()}</div>`,'DAY 1 / RÉSUMÉ DESK');const f=$('#resumeForm');f.oninput=()=>{project.resume=readForm(f);project.resumeComplete=false;laterSave()};f.onsubmit=e=>{e.preventDefault();project.resume=readForm(f);const issues=C.checkResume(project.persona,project.resume);if(issues.length){save();$('#formFeedback').innerHTML=`<div class="error-box"><b>Review these details</b><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`;return}project.resumeComplete=true;note('completed','Completed a practice résumé for '+job().title);$('#formFeedback').innerHTML='<div class="success-box"><b>Résumé saved.</b><p>Your contact details, education, experience, and skills are ready for the application desk.</p><button type="button" class="primary" data-travel="applications">Walk to applications →</button> <button type="button" class="quiet" data-print="resume">Print résumé</button></div>';};}
function openApplication(){if(!project?.resumeComplete)return toast('Finish and check your résumé at the résumé desk first.');if(project.applicationComplete)return assignmentBrief();showDialog('Apply for '+job().title,`<div class="split-form"><form id="applicationForm"><p><b>${esc(job().employer)}</b> · Practice application</p><p class="fine">The job interest is chosen. Your department will be assigned after this application is complete.</p><div class="form-grid">${fields(project.application,[['name','Full practice name'],['address','Street address'],['city','City'],['phone','Practice phone','tel'],['email','Practice email','email'],['employer','Most recent employer'],['jobTitle','Most recent job title'],['from','Employed from','month'],['to','Employed through','month'],['reference','First reference · full name'],['referencePhone','First reference · phone','tel'],['availability','Days & hours available'],['startDate','Available start date','date'],['reason','Why are you a good fit for this job?','textarea',true]])}<label class="wide"><input type="checkbox" name="certify" ${project.application.certify?'checked':''} required> I reviewed this practice application against my fictional background sheet.</label></div><div id="formFeedback" role="status"></div><div class="button-row"><button class="primary">Submit practice application</button></div><p class="fine">This is submitted inside the school simulation. It does not contact a real employer.</p></form>${backgroundSheet()}</div>`,'DAY 2 / APPLICATION DESK');const f=$('#applicationForm');f.oninput=()=>{project.application=readForm(f);laterSave()};f.onsubmit=e=>{e.preventDefault();project.application=readForm(f);const issues=C.checkApplication(project.persona,project.application);if(issues.length){save();$('#formFeedback').innerHTML=`<div class="error-box"><ul>${issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`;return}project.applicationComplete=true;project.assignment=C.assignment(actor,job(),project.cycle);note('completed','Submitted practice application; assigned '+project.assignment.title);assignmentBrief()};}
function assignmentBrief(){if(!project?.assignment)return openApplication();const j=job(),a=project.assignment,tasks=j.roles[a.roleIndex].tasks;showDialog('Your supervisor has an assignment.',`<span class="day-chip">ASSIGNMENT ${esc(a.shiftCode)}</span><h3 style="font:700 33px Georgia">${esc(a.title)}</h3><p><b>${esc(j.employer)}</b> · ${esc(j.title)}</p><p class="instruction">“${esc(project.persona.name)}, today you are assigned to ${esc(a.title)}. Follow the station order, check your work, and ask for help when needed.”</p><ol>${tasks.map(t=>`<li><b>${esc(t.title)}</b><p class="fine">${esc(t.brief)}</p></li>`).join('')}</ol><p class="fine">This is a career preview. Advanced career stations practice workplace organization and records; they do not award professional qualifications.</p><div class="button-row"><button class="primary" data-clock="in">${project.shift?project.shift.endedAt?'Review my completed shift':'Continue my assigned shift':'Clock in & walk to my station'} →</button><button class="quiet" data-print="application">Print application</button></div>`,'DAY 3 / SUPERVISOR BRIEF');}
function clockIn(){if(!project?.applicationComplete||!project.assignment)return;if(project.shift?.endedAt){closeDialog();view='portfolio';render();return}if(!project.shift){project.shift=C.newShift(project,job());note('action','Clocked in to assigned '+project.assignment.title,{service:'Workplace Readiness Training'})}closeDialog();floor='work';view='campus';render();const first=world?.stations.find(s=>s.index===nextTaskIndex());if(first)world.target={x:first.x,y:first.y+70,id:first.id};}
function renderPortfolio(){const p=project,j=job();app.innerHTML=hero('Your work has a story.','Keep your practice ID, résumé, application, and shift evidence together. Print the pieces you need for class.',p?'CAREER FOLDER':'LET’S BEGIN')+(p?journey():'')+`<section class="section-pad">${!p?'<div class="empty"><p>Your folder starts with a practice identity.</p><button class="primary" data-travel="id">Visit the identity desk</button></div>':`<div class="portfolio-grid"><article>${idCard()}<h2>ID & background</h2><p>${esc(j.title)} · Complete fictional details for applications and résumé building.</p><button class="primary" data-print="identity">Print ID & background</button></article><article><span class="eyebrow">DAY 1 / DAY 2</span><h2>Your application materials.</h2><p>Résumé: <b>${p.resumeComplete?'Checked & saved':'Draft / not yet checked'}</b></p><p>Application: <b>${p.applicationComplete?'Submitted in the simulation':'Not submitted'}</b></p><div class="button-row"><button class="secondary" data-print="resume">Print résumé</button><button class="secondary" data-print="application">Print application</button></div><button class="quiet" data-travel="resume">Continue résumé</button></article><article><span class="eyebrow">DAY 3 / ASSIGNED SHIFT</span><h2>${esc(p.assignment?.title||'Your role is coming.')}</h2><p>${p.assignment?'Supervisor-assigned role at '+esc(j.employer):'Finish your résumé and application to receive a role.'}</p>${p.shift?`<div class="metrics"><div><strong>${p.shift.tasks.filter(t=>t.completedAt).length}/${p.shift.tasks.length}</strong>stations done</div><div><strong>${p.shift.corrections}</strong>corrections</div><div><strong>${Math.floor(p.shift.activeSeconds/60)}m</strong>active practice</div></div>`:''}<div class="button-row"><button class="primary" data-print="report">Print activity report</button>${p.assignment?'<button class="quiet" data-travel="work">Continue shift</button>':''}</div></article></div><section class="side-card" style="margin-top:20px"><h2>Reflect on your work.</h2><label class="field-label" for="reflection">What went well, what needed a correction, and what will you practice next?</label><textarea id="reflection" class="transcript-input" maxlength="3000" data-monitor-private>${esc(p.reflection||'')}</textarea><button class="secondary" id="saveReflection">Save reflection</button></section><h2 style="font-family:Georgia">Your activity history</h2><div class="timeline">${p.events.slice(-20).reverse().map(e=>`<p><time>${new Date(e.at).toLocaleString()}</time>${esc(e.summary)}</p>`).join('')||'<p>Your school activity will appear here.</p>'}</div>`}${archive.length?`<section class="side-card"><h2>Earlier career projects</h2><p>Your previous ${archive.length} project${archive.length===1?' is':'s are'} kept here.</p>${archive.map((p,i)=>`<button class="quiet" data-archive="${i}">${esc(D.jobs.find(j=>j.id===p.persona.jobId)?.title||p.persona.jobId)} · Print folder</button>`).join(' ')}</section>`:''}<div class="button-row"><button class="quiet" data-nav="careers">Explore all 50 careers</button><a class="quiet" href="transition-town.html?school=1">Save & return to school</a></div></section>`;if($('#saveReflection'))$('#saveReflection').onclick=()=>{project.reflection=$('#reflection').value.trim();if(save()){note('completed','Saved a career-lab reflection');toast('Reflection saved.')}};}
function printFile(type,fromArchive){if(!project)return toast('Create your practice ID first.');let p=project;const real=project;if(fromArchive!==undefined){p=archive[fromArchive];project=p}const j=job(),r=p.resume||{},a=p.application||{},s=p.shift,meta=`<p class="print-meta">TRANSITION TOWN SCHOOL · Learner: ${esc(actor)} · Printed ${new Date().toLocaleDateString()} · FICTIONAL CLASSROOM PRACTICE</p>`;let html='';
if(type==='identity'||type==='all')html+=`<h1>My Career Exploration Background</h1>${meta}${idCard(p.persona)}${backgroundSheet(p.persona,false)}<p class="print-meta">The TT state code, 00000 ZIP, phone, email, employers, education and references are invented for classroom practice. Use this sheet to complete your school résumé and application.</p>`;
if(type==='resume'||type==='all')html+=`<div class="${type==='all'?'page-break':''}"><h1>${esc(r.name||p.persona.name)}</h1><p>${esc(r.address||'')} · ${esc(p.persona.city)}</p><p>${esc(r.phone||'')} · ${esc(r.email||'')}</p>${meta}<p class="print-meta">${p.resumeComplete?'Checked practice résumé':'Practice résumé draft'}</p><h2>Career objective</h2><p>${lines(r.objective||'Not completed')}</p><h2>Education</h2><p>${lines(r.education||'Not completed')}</p><h2>Experience</h2><p>${lines(r.experience||'Not completed')}</p><h2>Skills</h2><p>${lines(r.skills||'Not completed')}</p></div>`;
if(type==='application'||type==='all')html+=`<div class="${type==='all'?'page-break':''}"><h1>Practice Job Application</h1>${meta}<p><b>Career:</b> ${esc(j.title)} · <b>Employer:</b> ${esc(j.employer)}</p><p>Status: ${p.applicationComplete?'Submitted within the simulation':'Draft'}</p><table>${[['Full name','name'],['Street address','address'],['City','city'],['Phone','phone'],['Email','email'],['Previous employer','employer'],['Previous job title','jobTitle'],['Employed from','from'],['Employed through','to'],['Reference','reference'],['Reference phone','referencePhone'],['Availability','availability'],['Start date','startDate'],['Why I fit this job','reason']].map(([label,key])=>`<tr><th>${label}</th><td>${lines(a[key]||'Not completed')}</td></tr>`).join('')}</table>${p.assignment?`<h2>School supervisor assignment</h2><p>${esc(p.assignment.title)} · ${esc(p.assignment.shiftCode)}</p>`:''}</div>`;
if(type==='report'||type==='all')html+=`<div class="${type==='all'?'page-break':''}"><h1>Career Lab Activity Report</h1>${meta}<p><b>Career:</b> ${esc(j.title)}<br><b>Assigned role:</b> ${esc(p.assignment?.title||'Not assigned')}</p><p><b>Résumé:</b> ${p.resumeComplete?'Checked':'In progress'} · <b>Application:</b> ${p.applicationComplete?'Submitted in simulation':'In progress'}</p>${s?`<p>Shift began: ${new Date(s.startedAt).toLocaleString()}<br>Shift ended: ${s.endedAt?new Date(s.endedAt).toLocaleString():'In progress'}<br>Active task practice: ${Math.floor(s.activeSeconds/60)} min ${s.activeSeconds%60} sec · Corrections: ${s.corrections}</p><table><thead><tr><th>Assigned station</th><th>Status</th><th>Corrections</th><th>Completed</th></tr></thead><tbody>${s.tasks.map((t,i)=>`<tr><td>${esc(j.roles[s.roleIndex].tasks[i].title)}</td><td>${t.completedAt?'Completed':'In progress / not started'}</td><td>${t.corrections}</td><td>${t.completedAt?new Date(t.completedAt).toLocaleString():'—'}</td></tr>`).join('')}</tbody></table>`:'<p>No work shift has started.</p>'}<h2>Actual recorded activity</h2><table>${p.events.map(e=>`<tr><td>${new Date(e.at).toLocaleString()}</td><td>${esc(e.summary)}</td></tr>`).join('')}</table><h2>Learner reflection</h2><p>${lines(p.reflection||'Not recorded')}</p><h2>Teacher documentation</h2><p>Teacher selects the service practiced in this session: ____________________</p><p>Observed skills / support provided: __________________________________</p><p>Next-session plan: __________________________________________________</p><p class="print-meta">This report describes actions and corrections in a classroom simulation. It does not establish independent job mastery, professional credentials, attendance, or billable service time.</p></div>`;
$('#printArea').innerHTML=html;project=real;requestAnimationFrame(()=>window.print());}
function travel(id){if(id==='careers'){closeDialog();view='careers';render();return}if(id==='portfolio'){closeDialog();view='portfolio';render();return}if(!C.canVisit(project,id))return toast(!project?'Visit the identity desk first.':id==='applications'?'Finish and check your résumé first.':'Complete your résumé and application to receive your work assignment.');if(dialog.open)closeDialog();view='campus';floor='school';render();const point=world?.stations.find(s=>s.id===id);if(point){world.target={x:point.x,y:point.y+70,id};$('#worldHint').textContent='Walking to '+point.label+'…'};}
function openStation(id){if(id==='id')return openIdentity();if(id==='resume')return openResume();if(id==='applications')return openApplication();if(id==='work')return assignmentBrief();if(id==='careers'){view='careers';render();return}if(id==='portfolio'){view='portfolio';render();return}if(id.startsWith('task:'))openTask(Number(id.split(':')[1]));}
function startWorld(work){const canvas=$('#worldCanvas'),ctx=canvas.getContext('2d'),p=project?.position||{x:500,y:620};const stations=work?job().roles[project.assignment.roleIndex].tasks.map((t,i)=>({id:'task:'+i,x:[240,750,240,750][i]||500,y:i<2?245:515,label:t.title,color:['#278876','#bc7c48','#467c9f','#9672a2'][i%4],index:i})): [{id:'id',x:220,y:245,label:'01 · Identity desk',color:'#287b73'},{id:'resume',x:520,y:245,label:'02 · Résumé studio',color:'#bd7a4b'},{id:'applications',x:820,y:245,label:'03 · Applications',color:'#527e9b'},{id:'portfolio',x:220,y:515,label:'My career folder',color:'#7e739a'},{id:'careers',x:520,y:515,label:'Explore 50 careers',color:'#6f8b53'},{id:'work',x:820,y:515,label:'04 · Work experience',color:'#a0734f'}];
world={canvas,ctx,stations,x:work?500:p.x,y:work?390:p.y,target:null,moving:false,cooldown:Date.now()+1000,work,width:1100,height:760,tick:0};lastFrame=0;
canvas.onclick=e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*1100/r.width,y=(e.clientY-r.top)*760/r.height,near=stations.find(s=>Math.abs(x-s.x)<130&&y>s.y-115&&y<s.y+65);if(near){if(work&&near.index!==nextTaskIndex()){toast('Your supervisor assigned the highlighted station first.');return}if(!work&&!C.canVisit(project,near.id)){travel(near.id);return}world.target={x:near.x,y:near.y+70,id:near.id};$('#worldHint').textContent='Walking to '+near.label+'…'}else world.target={x:Math.max(60,Math.min(1040,x)),y:Math.max(160,Math.min(680,y))};canvas.focus({preventScroll:true})};
document.querySelectorAll('[data-dir]').forEach(b=>{const dir=b.dataset.dir;const release=()=>{keys[dir]=false};b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[dir]=true;world.target=null};b.onpointerup=release;b.onpointercancel=release;b.onlostpointercapture=release});raf=requestAnimationFrame(frame);}
function rounded(ctx,x,y,w,h,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fill()}
function text(ctx,label,x,y,size=15,color='#23483c',weight='bold'){ctx.font=`${weight} ${size}px Trebuchet MS, Arial`;ctx.textAlign='center';ctx.fillStyle=color;ctx.fillText(label,x,y)}
const schoolArt=new Image();schoolArt.src='assets/career-lab/art/school.webp?v=2';
function drawBuilding(s,t){const x=world.ctx,selected=world.work?s.index===nextTaskIndex():s.id===(!project?'id':!project.resumeComplete?'resume':!project.applicationComplete?'applications':'work'),done=world.work?project.shift?.tasks[s.index]?.completedAt:s.id==='id'?!!project:s.id==='resume'?project?.resumeComplete:s.id==='applications'?project?.applicationComplete:false;
const yy=s.y+60;x.save();x.shadowColor='#0008';x.shadowBlur=14;rounded(x,s.x-123,s.y-151,246,34,8,selected?'#f5bf63':'#12343fea');x.shadowBlur=0;text(x,s.label.length>31?s.label.slice(0,29)+'…':s.label,s.x,s.y-129,14,selected?'#29322e':'#fff');
x.strokeStyle=selected?'#ffd27c':'#ffffffa0';x.lineWidth=selected?4:2;x.beginPath();x.ellipse(s.x,yy,26+(selected?Math.sin(t*3)*3:0),11,0,0,Math.PI*2);x.stroke();text(x,done?'✓':selected?'↓':'•',s.x,yy-13,24,selected?'#ffdc9a':'#fff');x.restore();}

function frame(now){if(!world||!$('#worldCanvas'))return;const w=world,x=w.ctx,dt=Math.min(.035,(now-(lastFrame||now))/1000);lastFrame=now;const r=w.canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),cw=Math.round(r.width*dpr),ch=Math.round(r.height*dpr);if(w.canvas.width!==cw||w.canvas.height!==ch){w.canvas.width=cw;w.canvas.height=ch}x.setTransform(cw/1100,0,0,ch/760,0,0);const t=now/1000;w.tick=t;
if(schoolArt.complete&&schoolArt.naturalWidth){x.drawImage(schoolArt,0,0,1100,760)}else{x.fillStyle='#243d43';x.fillRect(0,0,1100,760);text(x,'Opening the career wing…',550,380,23,'#fff')}for(const s of w.stations)drawBuilding(s,t);
let dx=(keys.right?1:0)-(keys.left?1:0),dy=(keys.down?1:0)-(keys.up?1:0);if(dialog.open||document.hidden){dx=0;dy=0;w.moving=false}else{if(dx||dy)w.target=null;if(w.target){const dest=w.target;if(!dest.started){dest.started=now;dest.startX=w.x;dest.startY=w.y;dest.duration=Math.max(300,Math.hypot(dest.x-w.x,dest.y-w.y)/290*1000)}const progress=Math.min(1,(now-dest.started)/dest.duration),ease=progress<.5?2*progress*progress:1-Math.pow(-2*progress+2,2)/2;w.x=dest.startX+(dest.x-dest.startX)*ease;w.y=dest.startY+(dest.y-dest.startY)*ease;w.moving=progress<1;if(progress===1){const id=dest.id;w.target=null;if(id){w.cooldown=Date.now()+2000;openStation(id)}}dx=0;dy=0;}else{const length=Math.hypot(dx,dy);if(length){w.x=Math.max(55,Math.min(1045,w.x+dx/length*230*dt));w.y=Math.max(150,Math.min(685,w.y+dy/length*230*dt))}w.moving=!!length;}
if(!w.target&&w.moving&&Date.now()>w.cooldown){const s=w.stations.find(s=>Math.hypot(s.x-w.x,s.y+70-w.y)<23&&(!w.work||s.index===nextTaskIndex()));if(s){w.cooldown=Date.now()+2500;if(w.work||C.canVisit(project,s.id))openStation(s.id)}}}
window.TTDrawAvatar(x,w.x,w.y,resident().avatar,t,w.moving,.83);rounded(x,w.x-42,w.y+10,84,20,8,'#fffbea');text(x,actor,w.x,w.y+24,11,'#274c42');if(project&&!w.work&&Math.floor(now/2500)!==Math.floor((now-dt*1000)/2500)){project.position={x:w.x,y:w.y};save()}
if(world===w)raf=requestAnimationFrame(frame);}
function nextTaskIndex(){return project?.shift?.tasks.findIndex(t=>!t.completedAt)??0}
document.addEventListener('keydown',e=>{if(dialog.open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||view!=='campus'||!world)return;const key=({ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'})[e.key];if(key){e.preventDefault();keys[key]=true;world.target=null}if(e.key==='Enter'){const s=world.stations.find(s=>Math.hypot(s.x-world.x,s.y+70-world.y)<95);if(s){e.preventDefault();openStation(s.id)}}});document.addEventListener('keyup',e=>{const key=({ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'})[e.key];if(key)keys[key]=false});window.addEventListener('blur',()=>{keys={};activeAt=0});document.addEventListener('visibilitychange',()=>{keys={};activeAt=0;if(document.hidden)save()});
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;activeAt=Date.now();if(b.dataset.nav){if(b.dataset.nav==='help'){showDialog('Walk in. Try it. Build your future.',`<ol><li>Walk to <b>Identity</b> and choose a career interest. Print your practice background.</li><li>Use the background to type and check your <b>résumé</b>.</li><li>Fill out a <b>practice application</b>. Your supervisor assigns your role.</li><li>Clock in and walk to the highlighted <b>work station</b>. The view changes to your hands-on task.</li><li>Finish each assigned task, then walk to the next. Print your <b>career folder and activity report</b>.</li></ol><p>Move with arrow keys, WASD, the touch arrows, or tap a destination. Your existing Town avatar is used.</p><p>Drafts and task progress save on this device under your Town profile. Connected classroom activity logs receive completed actions and corrections.</p><p class="fine">The practice shift maps 10 active minutes to an 8-hour day. Finishing safely matters more than beating a timer.</p>`,'HOW TO PLAY');return}closeDialog();view=b.dataset.nav;floor='school';render();}else if(b.dataset.travel)travel(b.dataset.travel);else if(b.dataset.career)careerDetail(b.dataset.career);else if(b.dataset.identityJob)openIdentity(b.dataset.identityJob);else if(b.dataset.print)printFile(b.dataset.print);else if(b.dataset.archive!==undefined)printFile('all',Number(b.dataset.archive));else if(b.dataset.floor){floor=b.dataset.floor;render()}else if(b.dataset.clock)clockIn();else if(b.dataset.photo){const a=b.dataset.photo;if(a==='open')openPhoto();if(a==='start')startCamera();if(a==='capture')savePortrait($('#cameraVideo'));if(a==='avatar'){localStorage.removeItem('ttCareerPortraitMode:'+actor);localStorage.removeItem(photoKey());stopCamera();showID()}}else if(b.dataset.workAction)workAction(b.dataset.workAction,b.dataset);});
document.addEventListener('pointerdown',()=>{if(dialog.open&&activeTask>=0)activeAt=Date.now()},{passive:true});document.addEventListener('input',()=>{if(dialog.open&&activeTask>=0)activeAt=Date.now()},{passive:true});
setInterval(()=>{if(!project?.shift||project.shift.endedAt||activeTask<0||!dialog.open||document.hidden||!document.hasFocus()||Date.now()-activeAt>60000)return;project.shift.activeSeconds++;if(project.shift.activeSeconds%5===0)save();if($('#shiftClock'))$('#shiftClock').textContent=shiftTime();},1000);
function shiftTime(){const seconds=project?.shift?.activeSeconds||0,m=Math.min(480,Math.floor(seconds*.8));return String(8+Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0')+' · '+Math.floor(seconds/60)+'m active';}
const SIZES=['S','M','L','XL','XXL'];
const PRODUCTS=[{name:'Macaroni & cheese',kind:'box',color:'#e4a336',sku:'5101',location:'A1 · Bay 02 · Shelf 2',storage:'Dry grocery',price:249,action:'Behind earlier dates; labels forward'},{name:'Milk',kind:'milk',color:'#8bbec6',sku:'5102',location:'D1 · Bay 01 · Shelf 2',storage:'Refrigerated dairy',price:389,action:'Keep refrigerated; earlier dates in front'},{name:'Sandwich bread',kind:'bread',color:'#bc8755',sku:'5103',location:'B2 · Bay 03 · Shelf 1',storage:'Bread display',price:279,action:'Do not crush; labels forward'},{name:'Yellow onion',kind:'onion',color:'#cba36b',sku:'5104',location:'P1 · Bay 04 · Shelf 1',storage:'Dry produce bin',price:89,action:'Keep dry; rotate older sound stock forward'},{name:'Cereal',kind:'box',color:'#c96969',sku:'5105',location:'A1 · Bay 02 · Shelf 2',storage:'Dry grocery',price:429,action:'Behind earlier dates; labels forward'},{name:'Yogurt',kind:'milk',color:'#bb9ac7',sku:'5106',location:'D1 · Bay 01 · Shelf 2',storage:'Refrigerated dairy',price:139,action:'Keep refrigerated; earlier dates in front'},{name:'Soup · damaged can',kind:'can',color:'#a0a974',sku:'5107',location:'HOLD · Supervisor review',storage:'Hold — damaged package',price:189,action:'Set aside for supervisor; do not stock'}];
const STOCK_BINS=['A1 · Bay 02 · Shelf 2','D1 · Bay 01 · Shelf 2','B2 · Bay 03 · Shelf 1','P1 · Bay 04 · Shelf 1','HOLD · Supervisor review'];
function productSvg(kind='box',color='#d7a24e',label='TT',large=false){let cell=0;const name=label.toLowerCase();if(kind==='milk')cell=name.includes('yogurt')?5:1;else if(kind==='bread')cell=2;else if(kind==='onion')cell=3;else if(kind==='can')cell=6;else if(name.includes('cereal'))cell=4;else if(name.includes('coffee'))cell=7;return `<span class="product-svg product-art ${large?'garment-large':''}" role="img" aria-label="${esc(label)}" style="background-position:${cell%2*100}% ${Math.floor(cell/2)*100/3}%"></span>`}

function garmentSvg(color='#4c8d91',kind='Tops',large=false){const colors=['#428b8c','#d3a264','#8a76aa','#5b7caa','#ad6c75','#b36e77','#658a6c','#6f8eaf','#cf8d5a','#8c7ca9'],row=Math.max(0,colors.indexOf(color))%5,col=['Tops','Pants','Jackets'].indexOf(kind);return `<span class="${large?'garment-large':'product-svg'} garment-art" role="img" aria-label="${esc(kind)} garment" style="background-position:${Math.max(0,col)*50}% ${row*25}%"></span>`}

function taskContext(){const shift=project?.shift,r=shift?.tasks[activeTask],task=job()?.roles[shift?.roleIndex]?.tasks[activeTask];return {shift,r,task,s:r?.state}}
function initTask(){const {r,task,s,shift}=taskContext();if(!r||s.ready)return;r.startedAt=new Date().toISOString();s.ready=true;const seed=shift.id+':'+activeTask;
if(task.type==='clothes'){s.items=C.shuffle(SIZES.flatMap((size,i)=>[{size,label:size==='XXL'?'2XL':size,kind:['Tops','Pants','Jackets'][i%3],color:['#428b8c','#d3a264','#8a76aa','#5b7caa','#ad6c75'][i],fixture:i%2?'Shelf':'Rack'},{size,label:size,kind:['Jackets','Tops','Pants'][i%3],color:['#b36e77','#658a6c','#6f8eaf','#cf8d5a','#8c7ca9'][i],fixture:i%2?'Rack':'Shelf'}]),seed);s.index=0;s.inspected=false;s.hanger='';s.fixture='';}
else if(task.type==='stock'){s.items=C.shuffle(PRODUCTS,seed);s.index=0;s.scanned=false;s.placed=false;s.zoned=false;s.fronted=false;s.faced=false;s.rotated=false;}
else if(task.type==='cashier'){s.till=C.createTill();s.customer=0;s.scanned=0;s.change={};s.phase='scan';s.carts=[[PRODUCTS[0],PRODUCTS[1],PRODUCTS[2],PRODUCTS[3]],[PRODUCTS[4],PRODUCTS[0],PRODUCTS[1],PRODUCTS[5],PRODUCTS[2]],[PRODUCTS[3],PRODUCTS[2],PRODUCTS[5],PRODUCTS[0],PRODUCTS[1]]].map((a,i)=>C.shuffle(a,seed+i));}
else if(task.type==='custodian'){s.phase=0;s.cells=[];s.tool='';}
else if(task.type==='sequence'){s.order=C.shuffle(task.items.map((_,i)=>i),seed);if(s.order.every((v,i)=>v===i))s.order.reverse();}
else if(task.type==='sort'){s.done=[];s.selected=null;s.order=C.shuffle(task.items.map((_,i)=>i),seed);}
else if(task.type==='record')s.answers={};else if(task.type==='transcribe')s.text='';save();}
function openTask(index){if(!project?.shift)return assignmentBrief();const next=nextTaskIndex();if(index!==next){toast(index<next?'That station is already complete. Continue to your highlighted assignment.':'Complete the highlighted station first.');return}activeTask=index;feedback='';initTask();renderTask();}
function taskFeedback(message,ok=false){feedback=`<div class="${ok?'success-box':'error-box'}" role="status">${esc(message)}</div>`;}
function correction(message){const {r,shift}=taskContext();r.attempts++;r.corrections++;shift.corrections++;taskFeedback(message);note('correction',job().title+' · '+taskContext().task.title+': '+message,{task:taskContext().task.type,service:'Workplace Readiness Training'});renderTask();}
function unit(summary){const {r}=taskContext();r.attempts++;note('completed',summary,{task:taskContext().task.type,quantity:1,service:'Workplace Readiness Training'});}
function finishTask(summary){const {shift,r,task}=taskContext();if(!C.completeTask(shift,activeTask))return;r.attempts++;note('completed','Finished '+task.title+' · '+summary,{task:task.type,service:'Workplace Readiness Training'});if(shift.endedAt)note('completed','Finished assigned shift: '+project.assignment.title,{service:'Workplace Readiness Training'});showDialog(shift.endedAt?'Your shift is complete.':'Station complete.',`<div class="task-complete"><div class="completion-mark">✓</div><h3>${esc(task.title)}</h3><p>${esc(summary)}</p><p>${esc(task.why||'Check your work, leave your station ready for the next person, and follow your supervisor’s next assignment.')}</p><div class="metrics"><div><strong>${shift.tasks.filter(t=>t.completedAt).length}/${shift.tasks.length}</strong>stations complete</div><div><strong>${shift.corrections}</strong>corrections made</div><div><strong>${Math.floor(shift.activeSeconds/60)}m</strong>active practice</div></div><div class="button-row" style="justify-content:center"><button class="primary" data-work-action="return-floor">${shift.endedAt?'Review my career folder':'Walk to my next station'} →</button><button class="quiet" data-print="report">Print my report</button></div></div>`,'DAY 3 / PRACTICE EVIDENCE',true);activeAt=0;}
function workHUD(){return `<div class="work-hud"><span>${esc(project.persona.name)} · ${esc(project.assignment.title)}</span><span id="shiftClock">${shiftTime()}</span><span class="tag">10 active min ≈ 8 hr</span></div>`}
function renderTask(){const {r,task,s}=taskContext();if(!r||r.completedAt)return;const renderers={clothes:renderClothes,stock:renderStock,cashier:renderCashier,custodian:renderCustodian,sequence:renderSequence,sort:renderSort,record:renderRecord,transcribe:renderTranscribe};const fn=renderers[task.type];if(!fn)return toast('This station is unavailable. Your progress has been kept.');const content=fn(s,task);showDialog(task.title,workHUD()+content,'FIRST-PERSON WORK STATION',true);save();if(task.type==='custodian'&&s.phase===3)bindMop();if(task.type==='record')bindRecord();if(task.type==='transcribe')bindTranscript();if(task.type==='cashier'&&s.phase==='closing')bindTillCount();}
function panel(task,html='',progress=0){return `<aside class="task-panel"><span class="eyebrow">YOUR ASSIGNMENT</span><h3>${esc(task.title)}</h3><p>${esc(task.brief)}</p><div class="station-progress"><span style="width:${progress}%"></span></div>${feedback}${html}<p class="fine">Corrections are part of practice. Work carefully, then return to the floor for your next assignment.</p><button class="quiet" data-work-action="save-exit">Save & leave station</button></aside>`}
function renderClothes(s,task){const item=s.items[s.index];return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">APPAREL DEPARTMENT / ${s.index+1} OF ${s.items.length}</span><div class="garment-table">${garmentSvg(item.color,item.kind,true)}<div>${s.inspected?`<div class="tag-label">TRANSITION THREADS<b>${item.label}</b>${item.kind}<br>${item.fixture==='Shelf'?'FOLD · SHELF':'HANG · RACK'}<br>STYLE TT-${220+s.index}</div>`:'<button class="primary gold" data-work-action="inspect-tag">Look at sewn-in tag</button>'}</div></div><h3>1. Match the size marker</h3><div class="hanger-row">${SIZES.map(size=>`<button data-work-action="hanger" data-value="${size}" class="${s.hanger===size?'selected':''}" ${!s.inspected?'disabled':''}><svg viewBox="0 0 64 40" width="44" height="30" aria-hidden="true" style="display:block;margin:auto"><path d="M27 9c0-9 12-9 12-2 0 5-7 5-7 10L6 32q-3 4 2 4h48q5 0 2-4L32 17" fill="none" stroke="currentColor" stroke-width="3" stroke-linecap="round"/></svg>${size}</button>`).join('')}</div><h3>2. Choose how the item belongs on display</h3><div class="button-row"><button class="${s.fixture==='Rack'?'primary':'secondary'}" data-work-action="fixture" data-value="Rack" ${!s.inspected?'disabled':''}>Put on matching hanger</button><button class="${s.fixture==='Shelf'?'primary':'secondary'}" data-work-action="fixture" data-value="Shelf" ${!s.inspected?'disabled':''}>Fold for the size shelf</button></div><h3>3. Put it in the correct section</h3><div class="rack-grid">${['Tops','Pants','Jackets'].map((kind,i)=>`<button class="rack-zone" data-work-action="rack" data-value="${kind}" ${!s.inspected?'disabled':''}>${garmentSvg(['#87a890','#a2abc0','#c79577'][i],kind)}<b>${kind}</b><small>Size zones S · M · L · XL · XXL</small></button>`).join('')}</div></section>${panel(task,`<p><b>Read the actual tag.</b> The rack section, display method, and size marker all have to match. A tag marked 2XL belongs in XXL.</p><p>Inspected: ${s.inspected?'Yes':'Not yet'}<br>Size marker: ${s.hanger||'Not chosen'}<br>Display: ${s.fixture||'Not chosen'}</p>`,s.index/s.items.length*100)}</div>`}
function renderStock(s,task){const item=s.items[s.index];return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">STOCKING & ZONING / ${s.index+1} OF ${s.items.length}</span><div class="stock-cart">${productSvg(item.kind,item.color,item.name)}<div><b>${esc(item.name)}</b><p class="fine">Delivery tote · label TT-${item.sku}</p><button class="primary" data-work-action="scan-stock" ${s.scanned?'disabled':''}>Scan product label</button></div></div><div class="scan-screen">${s.scanned?`SKU ${item.sku}<strong>${esc(item.location)}</strong>${esc(item.storage)}<br>${esc(item.action)}`:'HANDHELD SCANNER<br><strong>Ready to scan</strong>Scan the item before choosing its home.'}</div><div class="stock-shelves">${STOCK_BINS.map((bin,i)=>`<button class="shelf-bin" data-work-action="shelf" data-value="${i}" ${!s.scanned||s.placed?'disabled':''}>${productSvg(PRODUCTS[i]?.kind||'box',PRODUCTS[i]?.color||'#9a9775',i===4?'HOLD':'TT')}<b>${esc(bin)}</b><small>${['Dry grocery','Refrigerated dairy','Bread display','Dry produce','Damaged / unclear stock'][i]}</small></button>`).join('')}</div>${s.placed?`<div class="instruction"><b>Zone the product correctly.</b>${item.storage.startsWith('Hold')?`<p>The package is damaged. Keep it out of saleable stock.</p><button class="primary" data-work-action="zone">Secure the supervisor hold tote</button>`:`<p>Already on shelf: <b>Nov 02</b> · Delivery label: <b>${Number(item.sku)%2===0?'Oct 28':'Nov 04'}</b></p><p>Keep earlier dates at the front.</p><div class="button-row"><button class="${s.rotated?'primary':'secondary'}" data-work-action="rotate-stock" data-value="front">Delivery in front</button><button class="${s.rotated?'primary':'secondary'}" data-work-action="rotate-stock" data-value="behind">Delivery behind existing stock</button></div><div style="display:flex;align-items:center;gap:15px;padding:12px;background:#e4dfc9;border-bottom:10px solid #aa8d63"><div style="transform:scale(${s.fronted?1:.72}) rotate(${s.faced?0:-90}deg);transition:transform .3s">${productSvg(item.kind,item.color,item.name)}</div><div><button class="${s.fronted?'primary':'secondary'}" data-work-action="pull-front">${s.fronted?'✓ At shelf edge':'Pull product to shelf edge'}</button><br><button class="${s.faced?'primary':'secondary'}" data-work-action="face-label">${s.faced?'✓ Label faces customer':'Turn label toward customer'}</button></div></div>`}${(item.storage.startsWith('Hold')?s.zoned:s.rotated&&s.fronted&&s.faced)?'<button class="primary" data-work-action="stock-next">Confirm location & take next product</button>':''}</div>`:''}</section>${panel(task,'<p>Match the complete aisle, bay, and shelf code. Similar packages can have different homes.</p><p>After stocking, rotate according to the scan card, pull products to the shelf edge, and turn labels toward the customer. Damaged packages go to supervisor hold.</p>',s.index/s.items.length*100)}</div>`}
function renderCashier(s,task){if(s.phase==='closing')return renderTillClosing(s,task);const cart=s.carts[s.customer],total=cart.reduce((a,p)=>a+p.price,0),tender=[2000,5000,2000][s.customer],scan=s.phase==='scan';return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">FRONT END / CUSTOMER ${s.customer+1} OF ${s.carts.length}</span><div class="checkout-scene"><div class="shopper"><span>“${scan?'I have everything right here.':'I’m paying with '+C.money(tender)+'.'}”</span><span class="shopper-face" aria-hidden="true"></span></div><div class="conveyor ${scan?'moving':''}" aria-label="Groceries moving along the checkout belt">${cart.slice(s.scanned).map(p=>productSvg(p.kind,p.color,p.name)).join('')||'<span style="color:#e6eee0">All items scanned · belt clear</span>'}</div><div class="scanner-pad"><div class="scanner-light" aria-hidden="true"></div><button class="primary" data-work-action="scan-checkout" ${!scan?'disabled':''}>Scan next grocery</button></div></div><div class="instruction">${scan?`Scan each item once. ${s.scanned}/${cart.length} scanned. Prices shown include the practice sales tax.`:`Payment received: <b>${C.money(tender)}</b><br>Total: <b>${C.money(total)}</b><br>Build the correct change using the notes and coins below.`}</div>${!scan?`<div class="cash-buttons">${C.denominations.map(d=>`<div><button data-work-action="cash-add" data-value="${d}">+ ${C.money(d)}<small>${s.change[d]||0} selected</small></button> <button data-work-action="cash-remove" data-value="${d}" aria-label="Remove one ${C.money(d)} from change">−</button></div>`).join('')}</div><p>Change on counter: <b>${C.money(C.countDrawer(s.change))}</b></p><div class="button-row"><button class="primary" data-work-action="give-change">Hand change to customer</button><button class="quiet" data-work-action="clear-change">Recount from zero</button></div>`:''}</section>${panel(task,`<div class="receipt"><center>TRANSITION TOWN MARKET<br>RECEIPT ${s.customer+1}</center>${cart.slice(0,s.scanned).map(p=>`<div class="receipt-row"><span>${esc(p.name)}</span><span>${C.money(p.price)}</span></div>`).join('')}<div class="receipt-row receipt-total"><span>TOTAL</span><span>${C.money(cart.slice(0,s.scanned).reduce((a,p)=>a+p.price,0))}</span></div><small>Tax included in each practice price.</small></div><p><b>Opening drawer:</b> ${C.money(s.till.opening)}<br><b>Completed cash sales:</b> ${C.money(s.till.cashSales)}</p>`,s.customer/s.carts.length*100)}</div>`}
function renderTillClosing(s,task){return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">SHIFT CLOSE / COUNT THE CASH DRAWER</span><p>Count the notes and coins in each compartment. Enter <b>pieces</b>, not dollar values.</p><form id="tillForm"><div class="drawer-grid">${C.denominations.map(d=>`<label class="drawer-pile"><strong>${C.money(d)}</strong><span class="bill-stack">${s.till.counts[d]} ${d>=100?'notes':'coins'}</span><span class="fine">Counted pieces</span><input type="number" min="0" step="1" required name="${d}" value="${esc(s.counts?.[d]??'')}" aria-label="Count of ${C.money(d)}"></label>`).join('')}</div><p>My counted cash: <b id="countedCash">${C.money(C.countDrawer(s.counts||{}))}</b></p><button class="primary">Balance & close my drawer</button></form></section>${panel(task,`<h3>Reconciliation</h3><p>Opening float: <b>${C.money(s.till.opening)}</b></p><p>Cash sales: <b>${C.money(s.till.cashSales)}</b><br>Refunds: <b>$0.00</b></p><p>Expected closing cash:<br><b>${C.money(s.till.opening+s.till.cashSales)}</b></p><p>A drawer balances when counted cash matches opening cash plus cash sales. Correct a shortage or overage before closing.</p>`,95)}</div>`}
function bindTillCount(){const f=$('#tillForm');f.oninput=()=>{const {s}=taskContext();s.counts=Object.fromEntries(new FormData(f));$('#countedCash').textContent=C.money(C.countDrawer(s.counts));laterSave()};f.onsubmit=e=>{e.preventDefault();const {s}=taskContext();s.counts=Object.fromEntries(new FormData(f));if(C.denominations.some(d=>!Number.isInteger(Number(s.counts[d]))||Number(s.counts[d])<0))return correction('Count whole, nonnegative pieces of each note and coin.');const counted=C.countDrawer(s.counts),expected=s.till.opening+s.till.cashSales;if(counted!==expected||C.denominations.some(d=>Number(s.counts[d])!==s.till.counts[d]))return correction('Your count does not match the drawer compartments. The total is '+(counted<expected?'short by ':'over by ')+C.money(Math.abs(counted-expected))+'. Recount each denomination.');finishTask('Scanned '+s.carts.reduce((a,c)=>a+c.length,0)+' groceries, served 3 cash customers, gave correct change, and balanced '+C.money(counted)+' closing cash.');};}
function renderCustodian(s,task){const phases=['Inspect & secure','Choose supplies','Prepare the area','Mop the marked floor','Check before reopening'],pct=Math.round((s.cells?.length||0)/180*100);return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">CUSTODIAL PRACTICE / ${phases[Math.min(s.phase,4)]}</span><div class="clean-room">${s.phase>0?'<span class="wet-sign">CAUTION<br>WET FLOOR</span>':''}<canvas id="mopCanvas" width="720" height="330" aria-label="Mop the water spill with your pointer. Keyboard users can clean sections with the button below." tabindex="0"></canvas>${s.phase<3?'<span style="position:absolute;left:40%;top:45%;color:#356f7b;background:#bfdfd4aa;border-radius:50%;padding:30px">Water spill</span>':''}</div>${s.phase===0?'<div class="instruction">A known water spill is on the tile walkway. Keep people clear before preparing the mop.</div><div class="button-row"><button class="primary" data-work-action="clean-sign">Set wet-floor sign & barrier</button><button class="quiet" data-work-action="clean-error">Start mopping immediately</button></div>':s.phase===1?'<h3>Choose supplies for this water spill</h3><div class="tool-row"><button data-work-action="clean-tool" data-value="mop">Mop, bucket & gloves</button><button data-work-action="clean-tool" data-value="vacuum">Electrical vacuum</button><button data-work-action="clean-tool" data-value="mix">Mix unlabeled cleaners</button></div>':s.phase===2?'<div class="instruction">The supervisor confirms this is water. The area is secured and the approved tools are ready.</div><button class="primary" data-work-action="clean-start">Put on gloves & begin approved cleanup</button>':s.phase===3?`<div class="instruction">Drag the mop across the entire marked floor. Unique sections cleaned: <b id="mopPercent">${pct}%</b>. Keep the sign in place.</div><div class="button-row"><button class="secondary" data-work-action="mop-section">Mop next floor section (keyboard)</button><button class="primary" data-work-action="clean-inspect" ${pct<90?'disabled':''}>Inspect the cleaned area</button></div>`:'<div class="instruction">The water is removed. Inspect the floor before removing the barrier.</div><button class="primary" data-work-action="clean-dry">Check that floor is dry, return supplies & remove sign</button>'}</section>${panel(task,`<p>1. Secure the work area.<br>2. Follow the approved supply instructions.<br>3. Clean the entire assigned surface.<br>4. Verify it is dry before reopening.</p><p>Report unknown liquids, broken glass, and unlabeled products to the supervisor.</p>`,s.phase/5*100)}</div>`}
function bindMop(){const c=$('#mopCanvas'),x=c.getContext('2d'),{s}=taskContext(),clean=new Set(s.cells);function paint(){x.clearRect(0,0,720,330);for(let row=0;row<10;row++)for(let col=0;col<18;col++){const id=row*18+col;if(!clean.has(id)){x.fillStyle=(row+col)%2?'#5a9cad88':'#6ba8b477';x.fillRect(col*40+2,row*33+2,36,29)}}if(pen){x.strokeStyle='#8a6b49';x.lineWidth=9;x.beginPath();x.moveTo(pen.x,pen.y-70);x.lineTo(pen.x,pen.y);x.stroke();rounded(x,pen.x-28,pen.y-8,56,20,5,'#ebd8a5')}}paint();
const scrub=e=>{const box=c.getBoundingClientRect(),px=(e.clientX-box.left)/box.width*720,py=(e.clientY-box.top)/box.height*330;pen={x:px,y:py};const col=Math.floor(px/40),row=Math.floor(py/33);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const cc=col+dx,rr=row+dy;if(cc>=0&&cc<18&&rr>=0&&rr<10)clean.add(rr*18+cc)}s.cells=[...clean];$('#mopPercent').textContent=Math.round(clean.size/180*100)+'%';const b=$('[data-work-action="clean-inspect"]');b.disabled=clean.size<162;activeAt=Date.now();paint()};c.onpointerdown=e=>{e.preventDefault();c.setPointerCapture(e.pointerId);scrub(e)};c.onpointermove=e=>{if(e.buttons)scrub(e)};c.onpointerup=()=>{save();pen=null;paint()};c.onpointercancel=()=>{save();pen=null};}
function renderSequence(s,task){return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">WORK PROCEDURE / PUT THE ACTIONS IN ORDER</span><div class="document-sheet">Supervisor brief: ${esc(task.brief)}</div><ol class="sequence-list">${s.order.map((idx,i)=>`<li draggable="true" data-order-index="${i}"><span class="step-number">${i+1}</span><span>${esc(task.items[idx])}</span><button data-work-action="order-up" data-value="${i}" aria-label="Move step ${i+1} up" ${i===0?'disabled':''}>↑</button><button data-work-action="order-down" data-value="${i}" aria-label="Move step ${i+1} down" ${i===s.order.length-1?'disabled':''}>↓</button></li>`).join('')}</ol><button class="primary" data-work-action="check-sequence">Submit my work procedure</button></section>${panel(task,'<p>Read every action before starting. Move the actions with the up and down buttons, then submit the complete sequence.</p><p>Look for preparation, verification, work, and documentation steps.</p>',0)}</div>`}
function renderSort(s,task){return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">WORKSTATION / ROUTE EACH ITEM</span><p>Select an item, then choose its correct destination.</p><div class="sort-workspace"><div class="sort-items">${s.order.map(i=>`<button class="sort-item ${s.selected===i?'selected':''}" data-work-action="select-sort" data-value="${i}" ${s.done.includes(i)?'disabled':''}>${s.done.includes(i)?'✓ ':''}${esc(task.items[i].label)}</button>`).join('')}</div><div class="sort-bins">${task.bins.map((bin,i)=>`<button class="sort-bin" data-work-action="sort-bin" data-value="${i}">${esc(bin)}<small>${s.done.filter(n=>task.items[n].target===bin).length} correctly routed</small></button>`).join('')}</div></div></section>${panel(task,`<p><b>${s.done.length}/${task.items.length}</b> items routed.</p><p>Selected: ${s.selected===null?'Choose an item':esc(task.items[s.selected].label)}</p><p>${s.selected===null?'Read the entire label. If an item needs supervisor review, route it rather than guessing.':esc(task.items[s.selected].note||'Match the full request to the correct destination.')}</p>`,s.done.length/task.items.length*100)}</div>`}
function renderRecord(s,task){return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">DOCUMENTATION DESK / COPY ACCURATE DETAILS</span><article class="document-sheet"><b>WORKPLACE SOURCE PACKET</b><br>${esc(task.document)}</article><form id="workRecordForm"><div class="record-fields">${task.fields.map((f,i)=>`<label>${esc(f.label)}<input name="field${i}" value="${esc(s.answers?.['field'+i]||'')}" required autocomplete="off"></label>`).join('')}</div><div class="button-row"><button class="primary">Verify & file this work record</button><button type="button" class="quiet" data-work-action="read-source">Read source aloud</button></div></form></section>${panel(task,'<p>Use the source packet on your work desk. Check names, record numbers, dates, times, and quantities. Every requested answer is in the source.</p>',0)}</div>`}
function bindRecord(){const f=$('#workRecordForm');f.oninput=()=>{taskContext().s.answers=Object.fromEntries(new FormData(f));laterSave()};f.onsubmit=e=>{e.preventDefault();const {task,s}=taskContext();s.answers=Object.fromEntries(new FormData(f));const wrong=task.fields.filter((field,i)=>C.normalize(s.answers['field'+i])!==C.normalize(field.answer));if(wrong.length)return correction('Review '+wrong.map(f=>f.label).join(', ')+'. Match the workplace source packet exactly.');finishTask('Verified and filed '+task.fields.length+' accurate details from the assigned source record.');};}
function renderTranscribe(s,task){return `<div class="task-layout"><section class="task-stage immersive-stage"><span class="eyebrow">COMMUNICATION DESK / RECORD THE EXACT MESSAGE</span><div class="document-sheet"><b>SOURCE MESSAGE</b><br>${esc(task.text)}</div><button class="secondary" data-work-action="read-source">Listen to the source</button><form id="transcriptForm"><label class="field-label" for="transcript">Type the message accurately. Keep names, numbers, and meaning intact.</label><textarea id="transcript" class="transcript-input" required spellcheck="false">${esc(s.text)}</textarea><div class="button-row"><button class="primary">Verify & save my message</button></div></form></section>${panel(task,'<p>Workplace messages must preserve the source. Listen or read, type the message, then check it. Punctuation and letter case are not scored.</p>',0)}</div>`}
function bindTranscript(){const f=$('#transcriptForm');$('#transcript').oninput=()=>{taskContext().s.text=$('#transcript').value;laterSave()};f.onsubmit=e=>{e.preventDefault();const {task,s}=taskContext();s.text=$('#transcript').value;if(C.normalize(s.text)!==C.normalize(task.text))return correction('Compare the message with the source. Check the names, numbers, and wording before saving.');finishTask('Recorded an accurate workplace message without changing the source wording.');};}
function beep(){try{const AudioCtx=window.AudioContext||window.webkitAudioContext;if(!AudioCtx)return;const a=new AudioCtx(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=950;g.gain.value=.025;o.start();o.stop(a.currentTime+.065);o.onended=()=>a.close()}catch{}}
function workAction(a,data){if(a==='return-floor'){closeDialog();if(project.shift.endedAt){view='portfolio';floor='school'}else{view='campus';floor='work'}render();if(floor==='work'){const next=world?.stations.find(s=>s.index===nextTaskIndex());if(next)world.target={x:next.x,y:next.y+70,id:next.id};}return}if(a==='save-exit'){closeDialog();view='campus';floor='work';render();toast('Station progress saved. Return to the highlighted station to continue.');return}const {task,s,r}=taskContext();if(!r||r.completedAt)return;activeAt=Date.now();feedback='';
if(a==='inspect-tag'){s.inspected=true;}
else if(a==='hanger'){s.hanger=data.value;}
else if(a==='fixture'){s.fixture=data.value;}
else if(a==='rack'){const item=s.items[s.index];if(!s.inspected)return correction('Inspect the sewn-in tag before sorting the item.');if(s.hanger!==item.size||s.fixture!==item.fixture||data.value!==item.kind)return correction('Check the size marker, rack or shelf display, and department against the tag.');unit('Matched '+item.label+' '+item.kind+' to the '+item.fixture.toLowerCase()+' and correct size section.');s.index++;s.inspected=false;s.hanger='';s.fixture='';if(s.index===s.items.length)return finishTask('Read 10 clothing tags and matched sizes S, M, L, XL, and XXL to the correct hanger or shelf and section.');taskFeedback('Item returned to the correct section. Next garment is ready.',true);}
else if(a==='scan-stock'){s.scanned=true;beep();}
else if(a==='shelf'){const item=s.items[s.index];if(!s.scanned)return correction('Scan this product before selecting a shelf.');if(STOCK_BINS[Number(data.value)]!==item.location)return correction('Read the entire aisle, bay, and shelf code on the scanner. Check the storage area too.');s.placed=true;taskFeedback('Correct location. Finish the stock rotation and facing check.',true);}
else if(a==='zone'){s.zoned=true;}
else if(a==='rotate-stock'){const item=s.items[s.index],expected=Number(item.sku)%2===0?'front':'behind';if(data.value!==expected)return correction('Compare the two date labels. Earlier-dated saleable stock belongs at the front.');s.rotated=true;}
else if(a==='pull-front')s.fronted=true;
else if(a==='face-label')s.faced=true;
else if(a==='stock-next'){const item=s.items[s.index];if(!s.placed||!(item.storage.startsWith('Hold')?s.zoned:s.rotated&&s.fronted&&s.faced))return;unit('Scanned '+item.name+'; matched '+item.location+' and checked '+item.storage.toLowerCase()+'.');s.index++;s.scanned=false;s.placed=false;s.zoned=false;s.fronted=false;s.faced=false;s.rotated=false;if(s.index===s.items.length)return finishTask('Scanned 7 products, matched complete shelf codes, rotated and faced stock, and held a damaged package for review.');}
else if(a==='scan-checkout'){if(s.phase!=='scan')return;const cart=s.carts[s.customer];if(s.scanned>=cart.length)return;s.scanned++;beep();if(s.scanned===cart.length)s.phase='change';}
else if(a==='cash-add'||a==='cash-remove'){const d=Number(data.value);if(!C.denominations.includes(d))return;s.change[d]=Math.max(0,(s.change[d]||0)+(a==='cash-add'?1:-1));}
else if(a==='clear-change')s.change={};
else if(a==='give-change'){const total=s.carts[s.customer].reduce((a,p)=>a+p.price,0),tender=[2000,5000,2000][s.customer];try{C.settle(s.till,total,tender,s.change)}catch(e){return correction(e.message)}unit('Customer '+(s.customer+1)+': scanned groceries totalling '+C.money(total)+' and returned '+C.money(tender-total)+' correct change.');s.customer++;s.scanned=0;s.change={};s.phase=s.customer===s.carts.length?'closing':'scan';taskFeedback('Customer served. '+(s.phase==='closing'?'Now count and balance your cash drawer.':'The next customer is ready.'),true);}
else if(a==='clean-sign')s.phase=1;
else if(a==='clean-error')return correction('Secure the walkway with the sign and barrier before starting cleanup.');
else if(a==='clean-tool'){if(data.value!=='mop')return correction('Use the supervisor-approved mop, bucket, and gloves for this known water spill. Do not use electrical equipment or mix unknown products.');s.tool='mop';s.phase=2;}
else if(a==='clean-start')s.phase=3;
else if(a==='mop-section'){const next=Array.from({length:180},(_,i)=>i).filter(i=>!s.cells.includes(i)).slice(0,9);s.cells.push(...next);}
else if(a==='clean-inspect'){if(s.cells.length<162)return correction('Finish mopping the marked surface before inspecting.');s.phase=4;}
else if(a==='clean-dry')return finishTask('Secured a known water spill, selected approved supplies, cleaned '+Math.round(s.cells.length/180*100)+'% of the marked floor, checked dryness, and reopened the area.');
else if(a==='order-up'||a==='order-down'){const i=Number(data.value),j=i+(a==='order-up'?-1:1);if(j<0||j>=s.order.length)return;[s.order[i],s.order[j]]=[s.order[j],s.order[i]];}
else if(a==='check-sequence'){if(!s.order.every((n,i)=>n===i))return correction('Review which steps prepare the work, which perform it, and which verify and document it.');return finishTask('Put all '+task.items.length+' assigned workplace actions in the correct order.');}
else if(a==='select-sort')s.selected=Number(data.value);
else if(a==='sort-bin'){if(s.selected===null)return toast('Select an item before choosing a destination.');if(task.items[s.selected].target!==task.bins[Number(data.value)])return correction('That item needs a different destination. Re-read the complete label and the supervisor’s brief.');s.done.push(s.selected);s.selected=null;if(s.done.length===task.items.length)return finishTask('Correctly routed '+task.items.length+' workplace items to their assigned destinations.');taskFeedback('Item routed correctly. Choose the next item.',true);}
else if(a==='read-source'){if(!window.speechSynthesis)return toast('Read-aloud is not available in this browser. The source text is on your desk.');window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(task.document||task.text);u.rate=.9;window.speechSynthesis.speak(u);return;}
renderTask();}
load();render();
window.TTCareerLab={get actor(){return actor},get project(){return project},get view(){return view},get floor(){return floor},travel,openStation,clockIn,render};
})();
